                <h4 className="text-xl font-bold mb-4">{item.title}</h4>
                <div className="flex gap-3">
                  <div className="w-10 h-10 rounded-full bg-white/20 backdrop-blur-md flex items-center justify-center hover:bg-pink-600 transition-colors">
                    <Search size={18} />
                  </div>
                  <div className="w-10 h-10 rounded-full bg-white/20 backdrop-blur-md flex items-center justify-center hover:bg-pink-600 transition-colors">
                    <ExternalLink size={18} />
