const Header: React.FC = () => {
  const [isScrolled, setIsScrolled] = useState(false);
  const [isMenuOpen, setIsMenuOpen] = useState(false);

  useEffect(() => {
    const handleScroll = () => {
      setIsScrolled(window.scrollY > 20);
    };
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const scrollToSection = (e: React.MouseEvent, id: string) => {
    e.preventDefault();
    const element = document.getElementById(id);
    if (element) {
      const offset = 80; // Compensação da altura do header fixo
      const bodyRect = document.body.getBoundingClientRect().top;
      const elementRect = element.getBoundingClientRect().top;
      const elementPosition = elementRect - bodyRect;
      const offsetPosition = elementPosition - offset;

      window.scrollTo({
        top: offsetPosition,
        behavior: 'smooth'
      });
    }
    setIsMenuOpen(false);
  };

  return (
    <header className={`fixed top-0 left-0 right-0 z-50 transition-all duration-300 ${isScrolled ? 'bg-white/95 backdrop-blur-md shadow-sm py-2' : 'bg-transparent py-4'}`}>
      <div className="container mx-auto px-6 flex justify-between items-center">
        <a href="#" className="flex items-center gap-2 group">
          <div className="w-10 h-10 bg-rosé rounded-full flex items-center justify-center text-white font-bold text-xl group-hover:rotate-12 transition-transform shadow-md">M</div>
          <span className="text-xl font-bold tracking-tight text-marrom uppercase">
            {BRAND_NAME.split(' ')[0]}<span className="text-rosé">{BRAND_NAME.split(' ')[1]}</span>
          </span>
        </a>

        {/* Desktop Nav */}
        <nav className="hidden md:flex items-center gap-8">
          <button onClick={(e) => scrollToSection(e, 'servicos')} className="text-marrom/80 hover:text-rosé transition-colors font-medium text-sm uppercase tracking-wider">Serviços</button>
          <button onClick={(e) => scrollToSection(e, 'beneficios')} className="text-marrom/80 hover:text-rosé transition-colors font-medium text-sm uppercase tracking-wider">Por que nós?</button>
          <button onClick={(e) => scrollToSection(e, 'portfolio')} className="text-marrom/80 hover:text-rosé transition-colors font-medium text-sm uppercase tracking-wider">Portfólio</button>
          <button onClick={(e) => scrollToSection(e, 'depoimentos')} className="text-marrom/80 hover:text-rosé transition-colors font-medium text-sm uppercase tracking-wider">Depoimentos</button>
          <a 
            href={WHATSAPP_LINK}
            target="_blank"
            rel="noopener noreferrer"
            className="bg-marrom text-white px-6 py-2 rounded-full text-xs font-bold hover:bg-rosé transition-all active:scale-95 shadow-md uppercase tracking-widest"
          >
            Orçamento
          </a>
        </nav>

        {/* Mobile Toggle */}
        <button className="md:hidden text-marrom p-2 ml-auto" onClick={() => setIsMenuOpen(!isMenuOpen)}>
          {isMenuOpen ? <X size={28} /> : <Menu size={28} />}
        </button>
      </div>

      {/* Mobile Menu */}
      {isMenuOpen && (
        <div className="md:hidden absolute top-full left-0 right-0 bg-white border-t border-bege shadow-2xl p-8 flex flex-col gap-6 animate-in slide-in-from-top duration-300">
          <button onClick={(e) => scrollToSection(e, 'servicos')} className="text-marrom text-lg font-bold uppercase tracking-wider border-b border-nude pb-4 text-left">Serviços</button>
          <button onClick={(e) => scrollToSection(e, 'beneficios')} className="text-marrom text-lg font-bold uppercase tracking-wider border-b border-nude pb-4 text-left">Por que nós?</button>
          <button onClick={(e) => scrollToSection(e, 'portfolio')} className="text-marrom text-lg font-bold uppercase tracking-wider border-b border-nude pb-4 text-left">Portfólio</button>
          <button onClick={(e) => scrollToSection(e, 'depoimentos')} className="text-marrom text-lg font-bold uppercase tracking-wider border-b border-nude pb-4 text-left">Depoimentos</button>
          <a 
            href={WHATSAPP_LINK} 
            target="_blank" 
            rel="noopener noreferrer"
            className="bg-rosé text-white text-center py-4 rounded-xl font-bold text-lg shadow-lg"
          >
            Solicitar Orçamento no WhatsApp
          </a>
        </div>
      )}
    </header>
  );
};

